def transform(grid):
    """Replace every marker-3 cell with its 180-degree rotational counterpart."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = grid[h - 1 - r][w - 1 - c]
    return out
